package app

import("context";"fmt";"time";"github.com/redis/go-redis/v9";"go.mongodb.org/mongo-driver/bson";"go.mongodb.org/mongo-driver/mongo";"go.mongodb.org/mongo-driver/mongo/options")
type Repository struct { db *mongo.Database; redis *redis.Client }
func (r *Repository) setup(ctx context.Context) error { indexes:=[]mongo.IndexModel{{Keys:bson.D{{Key:"email",Value:1}},Options:options.Index().SetUnique(true)}};if _,e:=r.db.Collection("users").Indexes().CreateMany(ctx,indexes);e!=nil{return e}; pollIndexes:=[]mongo.IndexModel{{Keys:bson.D{{Key:"ownerId",Value:1},{Key:"createdAt",Value:-1}}}};if _,e:=r.db.Collection("polls").Indexes().CreateMany(ctx,pollIndexes);e!=nil{return e}; voteIndexes:=[]mongo.IndexModel{{Keys:bson.D{{Key:"pollId",Value:1},{Key:"voterId",Value:1}},Options:options.Index().SetUnique(true)},{Keys:bson.D{{Key:"pollId",Value:1}}}};_,e:=r.db.Collection("votes").Indexes().CreateMany(ctx,voteIndexes);return e }
func (r *Repository) counts(ctx context.Context,p *Poll)(map[string]int64,error){key:="poll:"+p.ID+":results"; vals,e:=r.redis.HGetAll(ctx,key).Result();if e!=nil{return nil,e};out:=map[string]int64{};if len(vals)==0{cur,e:=r.db.Collection("votes").Find(ctx,bson.M{"pollId":p.ID});if e!=nil{return nil,e};defer cur.Close(ctx);for _,o:=range p.Options{out[o.ID]=0};var v Vote;for cur.Next(ctx){if e=cur.Decode(&v);e!=nil{return nil,e};out[v.OptionID]++};args:=map[string]any{};for id,n:=range out{args[id]=n};if len(args)>0{if e=r.redis.HSet(ctx,key,args).Err();e!=nil{return nil,e}};if e=cur.Err();e!=nil{return nil,e};return out,nil};for id,value:=range vals{var n int64;if _,e:=fmt.Sscan(value,&n);e!=nil{return nil,e};out[id]=n};return out,nil}
func makeResults(p *Poll,counts map[string]int64)Results{var total int64;for _,o:=range p.Options{total+=counts[o.ID]};rows:=make([]ResultOption,0,len(p.Options));for _,o:=range p.Options{pct:=0.;if total>0{pct=float64(counts[o.ID])/float64(total)*100};rows=append(rows,ResultOption{ID:o.ID,Text:o.Text,Votes:counts[o.ID],Percentage:pct})};return Results{Poll:*p,Options:rows,TotalVotes:total}}
func resultKey(id string)string{return "poll:"+id+":results"};func updateChannel(id string)string{return "poll:"+id+":updates"};func (r *Repository) expiryKey(id string)string{return resultKey(id)+":expiry"};var _=time.Now
